import static org.junit.Assert.*;

/**
 * Unit tests for MultivariateNormalDistribution#density
 */
public class MultivariateNormalDistribution_density_TriageGen1Test {

    private static final double EPSILON = 1.0e-10;

    @Test
    public void testDensityWithCorrectDimension() throws Exception {
        double[] means = {0.0, 0.0};
        double[][] covariances = {
            {1.0, 0.0},
            {0.0, 1.0}
        };
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // For standard bivariate normal at mean [0,0]:
        // density = (2*PI)^(-2/2) * |I|^(-0.5) * exp(0)
        // density = (2*PI)^(-1) * 1 * 1 = 1 / (2 * PI)
        double[] vals = {0.0, 0.0};
        double expected = 1.0 / (2.0 * Math.PI);
        double actual = distribution.density(vals);

        Assert.assertEquals(expected, actual, EPSILON);
    }

    @Test
    public void testDensityWithOffsetMean() throws Exception {
        double[] means = {1.0, -1.0};
        double[][] covariances = {
            {1.0, 0.5},
            {0.5, 1.0}
        };
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Test density at a specific point
        double[] vals = {1.0, -1.0};
        // At the mean, the exponent term is exp(0) = 1
        // Det = (1*1 - 0.5*0.5) = 0.75
        // density = (2*PI)^(-2/2) * (0.75)^(-0.5) * 1
        double expected = (1.0 / (2.0 * Math.PI)) * (1.0 / Math.sqrt(0.75));
        double actual = distribution.density(vals);

        Assert.assertEquals(expected, actual, EPSILON);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testDensityWithDimensionMismatch() throws Exception {
        double[] means = {0.0, 0.0};
        double[][] covariances = {
            {1.0, 0.0},
            {0.0, 1.0}
        };
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Input dimension is 3, expected is 2
        double[] vals = {0.0, 0.0, 0.0};
        distribution.density(vals);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testDensityWithEmptyInput() throws Exception {
        double[] means = {0.0};
        double[][] covariances = {{1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Input dimension is 0, expected is 1
        double[] vals = {};
        distribution.density(vals);
    }

    @Test
    public void testDensityOneDimensional() throws Exception {
        double[] means = {5.0};
        double[][] covariances = {{4.0}}; // std dev = 2
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Point at mean
        double[] vals = {5.0};
        // density = (2*PI)^(-1/2) * (4)^(-0.5) * 1
        // density = 1 / (sqrt(2*PI) * 2)
        double expected = 1.0 / (Math.sqrt(2.0 * Math.PI) * 2.0);
        double actual = distribution.density(vals);

        Assert.assertEquals(expected, actual, EPSILON);
    }
}
